--
-- Name: amendements_senat; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.amendements_senat AS
 SELECT DISTINCT ON (amd.id, (TRIM(BOTH FROM sen.senmat))) amd.id,
    TRIM(BOTH FROM sen.senmat) AS senateur_matricule,
    amd.num AS numero,
    amd.typ AS type_amendement,
    amd.dis AS dispositif,
    amd.obj AS expose,
    (amd.datdep)::date AS date_depot,
    sor.lib AS sort_libelle,
    sor.cod AS sort_code,
    amdsen.nomuse AS auteur_nom,
    amdsen.prenomuse AS auteur_prenom,
    amdsen.grpid AS auteur_groupe_id,
    now() AS created_at,
    now() AS updated_at
   FROM (((public.senat_ameli_amd amd
     LEFT JOIN public.senat_ameli_amdsen amdsen ON (((amd.id = amdsen.amdid) AND (amdsen.rng = 1))))
     LEFT JOIN public.senat_ameli_sor sor ON ((amd.sorid = sor.id)))
     LEFT JOIN public.senat_senateurs_sen sen ON (((upper(TRIM(BOTH FROM amdsen.nomuse)) = upper(TRIM(BOTH FROM sen.sennomuse))) AND (upper(TRIM(BOTH FROM amdsen.prenomuse)) = upper(TRIM(BOTH FROM sen.senprenomuse))))))
  WHERE (amdsen.senid IS NOT NULL)
  ORDER BY amd.id, (TRIM(BOTH FROM sen.senmat)), amd.datdep DESC NULLS LAST;


