--

CREATE TABLE public.senat_dosleg_doc (
    docidt bigint NOT NULL,
    typdoccod character varying(3),
    docint character varying(255),
    docurl character varying(255),
    lecidt character(15),
    docdat timestamp without time zone,
    docnum bigint,
    sesann bigint,
    date_depot timestamp without time zone,
    doctitcou character varying(254),
    docdatsea timestamp without time zone
);


--
-- Name: dossiers_legislatifs_senat; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dossiers_legislatifs_senat AS
 SELECT doc.docidt AS id,
    doc.docnum AS numero,
    doc.sesann AS session_annee,
    doc.typdoccod AS type_document_code,
    doc.docint AS intitule,
    doc.doctitcou AS titre_court,
    doc.docurl AS url_senat,
    (doc.date_depot)::date AS date_depot,
    (doc.docdat)::date AS date_document,
    (doc.docdatsea)::date AS date_seance,
    now() AS created_at,
    now() AS updated_at
   FROM public.senat_dosleg_doc doc
  ORDER BY doc.date_depot DESC NULLS LAST, doc.docnum DESC;


