    CONSTRAINT groupes_parlementaires_position_politique_check CHECK (((position_politique)::text = ANY (ARRAY[('extreme_gauche'::character varying)::text, ('gauche'::character varying)::text, ('centre_gauche'::character varying)::text, ('centre'::character varying)::text, ('centre_droit'::character varying)::text, ('droite'::character varying)::text, ('extreme_droite'::character varying)::text, ('non_inscrit'::character varying)::text])))
