--

CREATE TABLE public.senat_senateurs_typscr (
    typscrcod character varying(12) NOT NULL,
    typscrlib character varying(120),
    syscredat timestamp without time zone,
    sysmajdat timestamp without time zone
);


--
-- Name: senateurs_scrutins; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.senateurs_scrutins AS
 SELECT scr.scrid AS id,
    scr.sesann AS session_annee,
    scr.scrnum AS numero,
    scr.typscrcod AS type_scrutin_code,
    typscr.typscrlib AS type_scrutin,
    (scr.scrdat)::date AS date_scrutin,
    scr.scrint AS intitule,
    scr.scrintext AS intitule_complet,
    scr.scrpou AS pour,
    scr.scrcon AS contre,
    scr.scrvot AS votants,
    scr.scrsuf AS suffrages_exprimes,
    scr.scrmaj AS majorite_requise,
        CASE
            WHEN (scr.scrpou > scr.scrcon) THEN 'Adopté'::text
            WHEN (scr.scrcon > scr.scrpou) THEN 'Rejeté'::text
            WHEN (scr.scrpou = scr.scrcon) THEN 'Égalité'::text
            ELSE 'Non déterminé'::text
        END AS resultat,
    scr.syscredat AS created_at,
    scr.sysmajdat AS updated_at
   FROM (public.senat_senateurs_scr scr
     LEFT JOIN public.senat_senateurs_typscr typscr ON (((scr.typscrcod)::text = (typscr.typscrcod)::text)))
  ORDER BY scr.scrdat DESC NULLS LAST, scr.scrnum DESC;


--
-- Name: scrutins_senat; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.scrutins_senat AS
 SELECT senateurs_scrutins.id,
    senateurs_scrutins.session_annee,
    senateurs_scrutins.numero,
    senateurs_scrutins.type_scrutin_code,
    senateurs_scrutins.type_scrutin,
    senateurs_scrutins.date_scrutin,
    senateurs_scrutins.intitule,
    senateurs_scrutins.intitule_complet,
    senateurs_scrutins.pour,
    senateurs_scrutins.contre,
    senateurs_scrutins.votants,
    senateurs_scrutins.suffrages_exprimes,
    senateurs_scrutins.majorite_requise,
    senateurs_scrutins.resultat,
    senateurs_scrutins.created_at,
    senateurs_scrutins.updated_at
   FROM public.senateurs_scrutins;


