--
-- Name: senateurs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.senateurs AS
 SELECT DISTINCT ON ((TRIM(BOTH FROM sen.senmat))) TRIM(BOTH FROM sen.senmat) AS id,
    TRIM(BOTH FROM sen.senmat) AS matricule,
        CASE
            WHEN ((qua.qualib)::text = 'Monsieur'::text) THEN 'M.'::character varying
            WHEN ((qua.qualib)::text = 'Madame'::text) THEN 'Mme'::character varying
            ELSE COALESCE(qua.qualib, 'M.'::character varying)
        END AS civilite,
    sen.sennomuse AS nom,
    sen.sennomuse AS nom_usuel,
    sen.senprenomuse AS prenom,
    sen.senprenomuse AS prenom_usuel,
        CASE
            WHEN ((sen.etasencod)::text = 'ACTIF'::text) THEN 'ACTIF'::text
            ELSE 'ANCIEN'::text
        END AS etat,
    (sen.sendatnai)::date AS date_naissance,
    (sen.sendatdec)::date AS date_deces,
    COALESCE(sen.sengrppolliccou, 'Non inscrit'::character varying) AS groupe_politique,
    sen.sengrppolcodcou AS groupe_politique_code,
    sen.sentypappcou AS type_appartenance_groupe,
    sen.sencomliccou AS commission_permanente,
    sen.sencomcodcou AS commission_permanente_code,
    lpad((sen.sencirnumcou)::text, 2, '0'::text) AS departement_code,
    sen.sencircou AS circonscription,
    sen.senburliccou AS fonction_bureau_senat,
    sen.senema AS email,
    sen.pcscod AS pcs_insee,
    sen.catprocod AS categorie_socio_pro,
    sen.sendespro AS description_profession,
    sen.sendespro AS profession,
    sen.sendaiurl AS wikipedia_url,
    wiki.photo_wikipedia_url,
    wiki.wikipedia_extract,
    wiki.wikipedia_last_sync,
    sen.syscredat AS created_at,
    sen.sysmajdat AS updated_at
   FROM ((public.senat_senateurs_sen sen
     LEFT JOIN public.senat_senateurs_qua qua ON (((sen.quacod)::text = (qua.quacod)::text)))
     LEFT JOIN public.senateurs_wikipedia wiki ON ((TRIM(BOTH FROM sen.senmat) = (wiki.senateur_matricule)::text)))
  ORDER BY (TRIM(BOTH FROM sen.senmat)), sen.sysmajdat DESC NULLS LAST;


--
-- Name: senateurs_backup_old; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.senateurs_backup_old (
    matricule character varying(10) NOT NULL,
    civilite character varying(10) NOT NULL,
    nom_usuel character varying(100) NOT NULL,
    prenom_usuel character varying(100) NOT NULL,
    etat character varying(255) NOT NULL,
    date_naissance date,
    date_deces date,
    groupe_politique character varying(100),
    type_appartenance_groupe character varying(50),
    commission_permanente character varying(100),
    circonscription character varying(100),
    fonction_bureau_senat character varying(100),
    email character varying(255),
    pcs_insee character varying(255),
    categorie_socio_pro character varying(255),
    description_profession character varying(255),
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    wikipedia_url character varying(255),
    wikipedia_photo character varying(255),
    wikipedia_extract text,
    CONSTRAINT senateurs_etat_check CHECK (((etat)::text = ANY (ARRAY[('ACTIF'::character varying)::text, ('ANCIEN'::character varying)::text])))
);


--
-- Name: COLUMN senateurs_backup_old.matricule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.senateurs_backup_old.matricule IS 'Matricule sénateur (ex: 21077M)';


--
-- Name: senateurs_commissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.senateurs_commissions AS
 SELECT DISTINCT ON (mc.senmat, mc.orgcod, mc.memcomdatdeb) mc.memcomid AS id,
    TRIM(BOTH FROM mc.senmat) AS senateur_matricule,
    mc.orgcod AS commission_code,
    COALESCE(com.evelib, mc.orgcod) AS commission_nom,
    (mc.memcomdatdeb)::date AS date_debut,
    (mc.memcomdatfin)::date AS date_fin,
        CASE
            WHEN (mc.memcomdatfin IS NULL) THEN true
            ELSE false
        END AS actif,
    COALESCE(mc.memcomtitsup, 'Membre'::character varying) AS fonction,
    now() AS created_at,
    now() AS updated_at
   FROM (public.senat_senateurs_memcom mc
     LEFT JOIN public.senat_senateurs_com com ON (((mc.orgcod)::text = (com.orgcod)::text)))
  ORDER BY mc.senmat, mc.orgcod, mc.memcomdatdeb;


