--
-- Name: senateurs_historique_groupes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.senateurs_historique_groupes AS
 SELECT DISTINCT ON (mg.senmat, mg.orgcod, mg.memgrpsendatent) mg.memgrpsenid AS id,
    TRIM(BOTH FROM mg.senmat) AS senateur_matricule,
    COALESCE(grp.grppollibcou, mg.orgcod) AS groupe_nom,
    mg.orgcod AS groupe_code,
    (mg.memgrpsendatent)::date AS date_debut,
    (mg.memgrpsendatsor)::date AS date_fin,
        CASE
            WHEN (mg.memgrpsendatsor IS NULL) THEN true
            ELSE false
        END AS actif,
    'Membre'::text AS type_appartenance,
    now() AS created_at,
    now() AS updated_at
   FROM (public.senat_senateurs_memgrpsen mg
     LEFT JOIN public.senat_senateurs_grppol grp ON (((mg.orgcod)::text = (grp.grppolcod)::text)))
  ORDER BY mg.senmat, mg.orgcod, mg.memgrpsendatent;


