--
-- Name: senateurs_mandats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.senateurs_mandats AS
 SELECT DISTINCT ON (elusen.senmat, elusen.eludatdeb, elusen.dptnum) elusen.eluid AS id,
    TRIM(BOTH FROM elusen.senmat) AS senateur_matricule,
    (elusen.eludatdeb)::date AS date_debut,
    (elusen.eludatfin)::date AS date_fin,
        CASE
            WHEN (elusen.eludatfin IS NULL) THEN true
            ELSE false
        END AS actif,
    lpad((elusen.dptnum)::text, 2, '0'::text) AS departement_code,
    dpt.dptlib AS departement_nom,
    dpt.dptlib AS circonscription,
    NULL::integer AS circonscription_numero,
    typman.typmanlib AS type_mandat,
    elusen.eluanndeb AS annee_debut,
    elusen.eluannfin AS annee_fin,
    NULL::integer AS numero_mandat,
    now() AS created_at,
    now() AS updated_at
   FROM ((public.senat_senateurs_elusen elusen
     LEFT JOIN public.senat_senateurs_dpt dpt ON ((elusen.dptnum = dpt.dptnum)))
     LEFT JOIN public.senat_senateurs_typman typman ON (((elusen.typmancod)::text = (typman.typmancod)::text)))
  WHERE ((elusen.typmancod)::text = 'SENAT'::text)
  ORDER BY elusen.senmat, elusen.eludatdeb DESC NULLS LAST, elusen.dptnum;


--
-- Name: senateurs_mandats_backup_old; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.senateurs_mandats_backup_old (
    id bigint NOT NULL,
    matricule character varying(10) NOT NULL,
    type_mandat character varying(255) NOT NULL,
    circonscription character varying(100),
    date_debut date NOT NULL,
    date_fin date,
