    numero_mandat integer,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    CONSTRAINT senateurs_mandats_type_mandat_check CHECK (((type_mandat)::text = ANY (ARRAY[('SENATEUR'::character varying)::text, ('DEPUTE'::character varying)::text, ('EUROPEEN'::character varying)::text, ('METROPOLITAIN'::character varying)::text, ('MUNICIPAL'::character varying)::text])))
);


