--
-- Name: senateurs_votes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.senateurs_votes AS
 SELECT v.votesid AS id,
    TRIM(BOTH FROM v.senmat) AS senateur_matricule,
    v.scrid AS scrutin_id,
    (scr.scrdat)::date AS date_vote,
    scr.scrint AS intitule,
    scr.scrintext AS intitule_complet,
        CASE
            WHEN ((v.posvotcod)::text = '0'::text) THEN 'pour'::character varying
            WHEN ((v.posvotcod)::text = '2'::text) THEN 'contre'::character varying
            WHEN ((v.posvotcod)::text = '3'::text) THEN 'abstention'::character varying
            WHEN ((v.posvotcod)::text = '4'::text) THEN 'non_votant'::character varying
            WHEN ((v.posvotcod)::text = '5'::text) THEN 'non_votant'::character varying
            ELSE v.posvotcod
        END AS "position",
        CASE
            WHEN (scr.scrpou > scr.scrcon) THEN 'Adopté'::text
            WHEN (scr.scrcon > scr.scrpou) THEN 'Rejeté'::text
            ELSE 'Égalité'::text
        END AS resultat_scrutin,
    scr.scrpou AS pour,
    scr.scrcon AS contre,
    scr.scrvot AS votants,
    now() AS created_at,
    now() AS updated_at
   FROM (public.senat_senateurs_votes v
     LEFT JOIN public.senat_senateurs_scr scr ON ((v.scrid = scr.scrid)))
  WHERE (TRIM(BOTH FROM v.senmat) IS NOT NULL)
  ORDER BY scr.scrdat DESC NULLS LAST;


