--
-- Name: topics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.topics (
    id bigint NOT NULL,
    title character varying(255) NOT NULL,
    description text NOT NULL,
    scope character varying(255) DEFAULT 'national'::character varying NOT NULL,
    region_id bigint,
    department_id bigint,
    type character varying(255) DEFAULT 'debate'::character varying NOT NULL,
    status character varying(255) DEFAULT 'draft'::character varying NOT NULL,
    author_id bigint NOT NULL,
    has_ballot boolean DEFAULT false NOT NULL,
    voting_opens_at timestamp(0) without time zone,
    voting_deadline_at timestamp(0) without time zone,
    ballot_type character varying(255),
    ballot_options json,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    scrutin_an_uid character varying(30),
    loi_cod character varying(20),
    idea_type character varying(30) DEFAULT 'debate'::character varying NOT NULL,
    votes_pour integer DEFAULT 0 NOT NULL,
    votes_contre integer DEFAULT 0 NOT NULL,
    score integer DEFAULT 0 NOT NULL,
    views_count integer DEFAULT 0 NOT NULL,
    slug character varying(300),
    published_at timestamp(0) without time zone,
    rejection_reason text,
    poll_type character varying(30),
    poll_max_choices smallint,
    poll_show_results_before_vote boolean DEFAULT false NOT NULL,
    poll_allow_change_vote boolean DEFAULT true NOT NULL,
    poll_ends_at timestamp(0) without time zone,
    debate_mode boolean DEFAULT false NOT NULL,
    commune_code_insee character varying(5),
    forum_categorie character varying(255),
    CONSTRAINT topics_ballot_type_check CHECK (((ballot_type)::text = ANY (ARRAY[('yes_no'::character varying)::text, ('multiple_choice'::character varying)::text, ('preferential'::character varying)::text]))),
    CONSTRAINT topics_scope_check CHECK (((scope)::text = ANY (ARRAY[('national'::character varying)::text, ('regional'::character varying)::text, ('departemental'::character varying)::text, ('communal'::character varying)::text, ('region'::character varying)::text, ('dept'::character varying)::text]))),
    CONSTRAINT topics_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('pending'::character varying)::text, ('published'::character varying)::text, ('rejected'::character varying)::text, ('archived'::character varying)::text, ('open'::character varying)::text, ('closed'::character varying)::text]))),
    CONSTRAINT topics_type_check CHECK (((type)::text = ANY (ARRAY[('debate'::character varying)::text, ('bill'::character varying)::text, ('referendum'::character varying)::text, ('idea'::character varying)::text, ('petition'::character varying)::text, ('question'::character varying)::text])))
);


